// ============================================
// ФУНКЦИИ ДЛЯ РАБОТЫ С МОДУЛЯМИ
// ============================================

function getAttachmentsByTypeMWIII(type) {
    return window.ATTACHMENTS_MWIII[type] ? window.ATTACHMENTS_MWIII[type].items : [];
}

function getAllAttachmentsMWIII() {
    const all = [];
    for (const type in window.ATTACHMENTS_MWIII) {
        all.push(...window.ATTACHMENTS_MWIII[type].items);
    }
    return all;
}

function getAttachmentById(id) {
    for (const type in window.ATTACHMENTS_MWIII) {
        const items = window.ATTACHMENTS_MWIII[type].items;
        for (const item of items) {
            if (item.id === id) return item;
        }
    }
    return null;
}

function getAttachmentByName(name) {
    for (const type in window.ATTACHMENTS_MWIII) {
        const items = window.ATTACHMENTS_MWIII[type].items;
        for (const item of items) {
            if (item.name === name) return item;
        }
    }
    return null;
}

// ============================================
// ФУНКЦИЯ ПРОВЕРКИ КОНФЛИКТОВ
// ============================================
function hasConflict(attId1, attId2) {
    if (!attId1 || !attId2) return false;
    
    const a1 = getAttachmentById(attId1);
    const a2 = getAttachmentById(attId2);
    if (!a1 || !a2) return false;
    
    if (a1.conflicts) {
        for (const conflict of a1.conflicts) {
            if (conflict === a2.id) return true;
            
            let categoryName = conflict;
            if (conflict.startsWith('category:')) {
                categoryName = conflict.replace('category:', '');
            }
            
            const categoryData = window.ATTACHMENTS_MWIII[categoryName];
            if (categoryData) {
                if (categoryData.items.some(item => item.id === a2.id)) {
                    return true;
                }
            }
        }
    }
    
    if (a2.conflicts) {
        for (const conflict of a2.conflicts) {
            if (conflict === a1.id) return true;
            
            let categoryName = conflict;
            if (conflict.startsWith('category:')) {
                categoryName = conflict.replace('category:', '');
            }
            
            const categoryData = window.ATTACHMENTS_MWIII[categoryName];
            if (categoryData) {
                if (categoryData.items.some(item => item.id === a1.id)) {
                    return true;
                }
            }
        }
    }
    
    return false;
}

// ============================================
// ФУНКЦИЯ ПРОВЕРКИ СОВМЕСТИМОСТИ
// ============================================
function isAttachmentCompatibleMWIII(attachment, weaponCategory, weaponName = null, currentAttachments = []) {
    if (!attachment || !weaponCategory) return false;
    
    if (attachment.exclude && Array.isArray(attachment.exclude)) {
        if (weaponName && attachment.exclude.includes(weaponName)) {
            return false;
        }
        if (attachment.exclude.includes(weaponCategory)) {
            return false;
        }
    }
    
    if (attachment.weaponRequirements && weaponName) {
        const requiredAttachments = attachment.weaponRequirements[weaponName];
        if (requiredAttachments) {
            const requiredArray = Array.isArray(requiredAttachments) ? requiredAttachments : [requiredAttachments];
            const hasRequired = requiredArray.some(requiredId =>
                currentAttachments.some(att => att.id === requiredId)
            );
            if (!hasRequired) {
                return false;
            }
        }
    }
    
    if (attachment.requires) {
        const hasRequiredModule = currentAttachments.some(att => att.id === attachment.requires);
        if (!hasRequiredModule) {
            return false;
        }
    }
    
    if (attachment.lockedWith && weaponName) {
        const lockedModules = attachment.lockedWith[weaponName];
        if (lockedModules) {
            const lockedArray = Array.isArray(lockedModules) ? lockedModules : [lockedModules];
            const hasLocked = lockedArray.some(moduleId =>
                currentAttachments.some(att => att.id === moduleId)
            );
            if (hasLocked) {
                return false;
            }
        }
    }
    
    for (const selected of currentAttachments) {
        if (hasConflict(attachment.id, selected.id)) {
            return false;
        }
    }
    
    if (attachment.compatibility === 'all') return true;
    
    if (Array.isArray(attachment.compatibility)) {
        if (attachment.compatibility.includes(weaponCategory)) {
            return true;
        }
        if (weaponName && attachment.compatibility.includes(weaponName)) {
            return true;
        }
        return false;
    }
    
    if (typeof attachment.compatibility === 'string') {
        return attachment.compatibility === weaponCategory || 
               (weaponName && attachment.compatibility === weaponName);
    }
    
    return false;
}

// Экспорт
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { 
        ATTACHMENTS_MWIII: window.ATTACHMENTS_MWIII,
        getAttachmentsByTypeMWIII,
        getAllAttachmentsMWIII,
        getAttachmentById,
        getAttachmentByName,
        isAttachmentCompatibleMWIII,
        hasConflict,
        generateRandomClassMWIII,
        generateAndValidateMWIII
    };
}

// ============================================
// ФУНКЦИЯ ГЕНЕРАЦИИ СЛУЧАЙНОГО КЛАССА
// ============================================
function generateRandomClassMWIII() {
    const weaponTypes = Object.keys(WEAPONS_MWIII);
    const randomType = weaponTypes[Math.floor(Math.random() * weaponTypes.length)];
    const weapons = WEAPONS_MWIII[randomType].weapons;
    const weaponName = weapons[Math.floor(Math.random() * weapons.length)];
    
    const availableSlots = ['optics', 'muzzles', 'barrels', 'underbarrels', 'rearGrips', 'stocks', 'magazines', 'bolts', 'conversionKits', 'triggerActions', 'combs', 'lasers', 'ammunitions'];
    const selected = [];
    
    for (const slot of availableSlots) {
        if (!window.ATTACHMENTS_MWIII[slot]) continue;
        const items = getAttachmentsByTypeMWIII(slot);
        let compatible = items.filter(att => 
            isAttachmentCompatibleMWIII(att, randomType, weaponName, selected)
        );
        
        if (compatible.length > 0) {
            const random = compatible[Math.floor(Math.random() * compatible.length)];
            selected.push(random);
        }
    }
    
    return {
        weapon: {
            category: randomType,
            name: weaponName
        },
        attachments: selected
    };
}

// ============================================
// ГЕНЕРАЦИЯ С ПРОВЕРКОЙ КОНФЛИКТОВ
// ============================================
function generateAndValidateMWIII() {
    let loadout;
    let attempts = 0;
    const maxAttempts = 100;
    
    do {
        loadout = generateRandomClassMWIII();
        attempts++;
        
        // Проверяем конфликты между всеми выбранными модулями
        let hasConflicts = false;
        for (let i = 0; i < loadout.attachments.length; i++) {
            for (let j = i + 1; j < loadout.attachments.length; j++) {
                if (hasConflict(loadout.attachments[i].id, loadout.attachments[j].id)) {
                    hasConflicts = true;
                    break;
                }
            }
            if (hasConflicts) break;
        }
        
        if (!hasConflicts) {
            return loadout;
        }
    } while (attempts < maxAttempts);
    
    return loadout;
}

// Экспорт
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { 
        ATTACHMENTS_MWIII: window.ATTACHMENTS_MWIII,
        getAttachmentsByTypeMWIII, 
        getAllAttachmentsMWIII,
        getAttachmentById,
        getAttachmentByName,
        isAttachmentCompatibleMWIII,
        hasConflict,
        generateRandomClassMWIII,
        generateAndValidateMWIII
    };
}